      reviewId,
      eventType: 'review_failed',
      payload: {
        code: 'review_execution_aborted',
        message,
        reason: 'manual_fail',
        priorStatus: review.status,
      },
    });
  }

  return {
    action: 'failed',
    review: await getReviewRun(env.DB, reviewId),
  };
}

